function basin(g, [x0, z0, x1, z1]) {
  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
    const rim = x === x0 || x === x1 || z === z0 || z === z1;
    if (rim) g.set(x, 1, z, ...B.slab("smooth_quartz", "bottom"));
    else g.set(x, 1, z, WATER);
  }
  return g;
}

