  for (let x = x0; x <= x1; x++) g.set(x, 6, z, ...B.stairs("quartz", "north"));
  for (let x = x0 + 1; x <= x1 - 1; x++) g.set(x, 7, z, ...B.stairs("quartz", "north"));
